import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.BKeRpnBD.js";const u=JSON.parse('{"title":"震下巽上 益：","description":"京氏易传 - 震下巽上 益：","frontmatter":{"title":"震下巽上 益：","description":"京氏易传 - 震下巽上 益："},"headers":[],"relativePath":"zh/classics/jingshi/045.md","filePath":"zh/classics/jingshi/045.md"}'),i={name:"zh/classics/jingshi/045.md"};function r(c,a,o,p,d,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"震下巽上-益",tabindex:"-1"},[l("震下巽上 益： "),e("a",{class:"header-anchor",href:"#震下巽上-益","aria-label":"Permalink to “震下巽上 益：”"},"​")],-1),e("p",null,"天地不交曰否。六二阴上柔刚，九四下降积阴，故为益。《易》曰：“损上益下”。雷动风行，男下女上。【震男，巽女。】阳益阴，君益于民之象也。互见坤，坤道柔顺。又外见艮，艮止阳益阴，止于阳，柔道行也。【内外顺动，风雷益。四象分明，刚柔定矣。】与震为飞伏。【庚辰土，辛酉金。】六三三公居世，上九宗庙为应。",-1),e("p",null,"建始甲辰至己酉，【清明，秋分。】积算起己酉至戊申，周而复始。土金入震巽。【起积配风雷益卦起宫。】",-1),e("p",null,"五星从位起岁星，【木星入卦。】计宿从位降庚辰，（虎易注：计宿，即是斗宿。）【二十八宿，分计宿入风雷益六二庚辰土上。】分气候二十八。【起二十八数，积算吉凶，周而复始。】",-1),e("p",null,"阴阳二木，合金土配象，四时运转，六位交分，休废旺生，吉凶见乎动爻。配日月星辰进退，运气升降，复当何位。【金、水、木、火、土。】",-1),e("p",null,"适变于外，阳入阴爻。二象健而动，属于天地也。【天阳，震雷亦阳也。二气相激，动而健，天行也。】阴阳相荡，次降入天雷无妄卦。",-1)])])}const _=s(i,[["render",r]]);export{u as __pageData,_ as default};
